/* Upstream expects the integrator to provide randombytes (declared in csprng_hash.h). */
void randombytes(unsigned char *x, unsigned long long xlen) {
    while (xlen > 0) {
        ssize_t r = getrandom(x, (size_t)xlen, 0);
        if (r <= 0) continue;
        x += r;
        xlen -= (unsigned long long)r;
    }
}

int crypto_sign_keypair(uint8_t *pk, uint8_t *sk) {
    CROSS_keygen((sk_t *)sk, (pk_t *)pk);
    return 0;
}
int crypto_sign_signature(uint8_t *sig, size_t *siglen,
                          const uint8_t *m, size_t mlen, const uint8_t *sk) {
    CROSS_sign((const sk_t *)sk, (const char *)m, (uint64_t)mlen, (CROSS_sig_t *)sig);
    *siglen = sizeof(CROSS_sig_t);
    return 0;
}
int crypto_sign_verify(const uint8_t *sig, size_t siglen,
                       const uint8_t *m, size_t mlen, const uint8_t *pk) {
    if (siglen != sizeof(CROSS_sig_t)) return -1;
    /* CROSS_verify returns 1 on success, 0 on failure */
    return CROSS_verify((const pk_t *)pk, (const char *)m, (uint64_t)mlen,
                        (const CROSS_sig_t *)sig) == 1 ? 0 : -1;
}
